let currentLang = "de";
const listeners = [];

export function detectLang() {
  const nav = (navigator.language || navigator.userLanguage || "de").slice(0, 2).toLowerCase();
  return LANG_CODES.includes(nav) ? nav : "en";
}

export function getLang() { return currentLang; }

export function setLang(code) {
  if (!LANG_CODES.includes(code)) code = "en";
  currentLang = code;
  try { localStorage.setItem(LANG_KEY, code); } catch (e) {}
  document.documentElement.setAttribute("lang", code);
  listeners.forEach(fn => { try { fn(code); } catch (e) {} });
}

export function initLang() {
  let saved = null;
  try { saved = localStorage.getItem(LANG_KEY); } catch (e) {}
  currentLang = (saved && LANG_CODES.includes(saved)) ? saved : detectLang();
  document.documentElement.setAttribute("lang", currentLang);
  return currentLang;
}

export function onLangChange(fn) { listeners.push(fn); }

// t("key", { var: value }) – falls back en -> de -> key.
export function t(key, vars) {
  let s = (T[currentLang] && T[currentLang][key]) ?? T.en[key] ?? T.de[key] ?? key;
  if (vars) for (const k in vars) s = s.replaceAll("{" + k + "}", vars[k]);
  return s;
}

export function roleName(roleKey) {
  const r = ROLE[currentLang] || ROLE.en;
  return (r.names && r.names[roleKey]) || (ROLE.en.names[roleKey]) || roleKey;
}

export function roleDesc(roleKey) {
  const r = ROLE[currentLang] || ROLE.en;
  return (r.desc && r.desc[roleKey]) || (ROLE.en.desc[roleKey]) || "";
}
